import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom"; // Importando useParams

const AdmInfCurso = () => {
  const { id } = useParams(); // Pega o id da URL
  const [curso, setCurso] = useState(null); // Estado para armazenar os dados do curso
  const [editMode, setEditMode] = useState(false); // Estado para modo de edição

  // Função para buscar os dados do curso pelo ID
  useEffect(() => {
    fetchCurso();
  }, [id]);

  const fetchCurso = async () => {
    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
      if (resposta.ok) {
        const dados = await resposta.json();
        setCurso(dados); // Atualiza o estado com os dados do curso
      } else {
        console.error("Erro ao buscar curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  if (!curso) return <p>Carregando...</p>; // Mostra "Carregando..." enquanto os dados não chegam

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={() => setEditMode(true)}>
            Editar
          </button>
        )}
      </div>
      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informação do Curso</h4>
          <p>
            <strong>{curso.nome}</strong>
          </p>
          <p>{curso.nivel}</p>
          <p>{curso.periodo}</p>
          <p>{curso.area}</p>
        </div>
        <div className="w-50 ps-4">
          <div className="mb-3">
            <label className="fw-bold">Professor</label>
            <p>{curso.professor}</p>
          </div>
          <label className="fw-bold">Alunos</label>
          <ul>
            {curso.alunos.map((aluno, index) => (
              <li key={index}>{aluno}</li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdmInfCurso;
